def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_me, last_opp = history[-1]

    opp_d = sum(1 for x in opp if x == 'D')
    opp_c = n - opp_d
    my_d = sum(1 for x in me if x == 'D')

    after_d_c = 0
    after_d_d = 0
    unprov_d = 0
    for i in range(1, n):
        prev_my = history[i - 1][0]
        opp_i = history[i][1]
        if prev_my == 'D':
            if opp_i == 'C':
                after_d_c += 1
            else:
                after_d_d += 1
        elif opp_i == 'D':
            unprov_d += 1

    w = min(12, n)
    rec_opp_d = sum(1 for x in opp[-w:] if x == 'D')
    rec_me_d = sum(1 for x in me[-w:] if x == 'D')
    rec_unprov_d = 0
    for i in range(max(1, n - w), n):
        if history[i - 1][0] == 'C' and history[i][1] == 'D':
            rec_unprov_d += 1

    if n >= 99:
        return 'D'

    if opp_c == 0 or (n >= 5 and opp_d * 10 >= n * 8):
        return 'D'
    if n >= 10 and opp_d * 3 >= n * 2:
        return 'D'
    if n >= 8 and rec_opp_d >= w:
        return 'D'
    if n >= 12 and unprov_d >= 4 and unprov_d * 4 >= opp_d * 3 and opp_d * 20 >= n * 9:
        return 'D'

    if last_opp == 'D':
        if n >= 2 and history[-2][0] == 'D':
            if opp_c * 10 < n * 4 or unprov_d >= 4 or rec_unprov_d >= 3:
                return 'D'
            return 'C'
        else:
            if (
                last_me == 'D'
                and opp_c * 10 >= n * 5
                and rec_unprov_d <= 2
                and unprov_d <= max(4, n // 5)
            ):
                return 'C'
            if rec_me_d >= 3 and rec_unprov_d <= 1 and opp_c * 10 >= n * 8:
                return 'C'
            return 'D'

    if last_opp == 'C':
        if opp_d * 5 >= n * 3:
            return 'D'

        if (
            after_d_c >= 1
            and after_d_d == 0
            and opp_c * 10 >= n * 9
            and unprov_d <= max(1, n // 10)
        ):
            if last_me == 'D' or (n >= 2 and history[-2][0] == 'D'):
                if n < 98:
                    return 'D'

        if n == 98:
            if (
                after_d_c >= 1
                and after_d_d == 0
                and opp_c * 10 >= n * 9
                and unprov_d <= max(1, n // 10)
            ):
                return 'D'
            return 'C'

        if last_me == 'D' and last_opp == 'C' and after_d_c == 0:
            return 'C'

        if (
            my_d == 0
            and opp_d == 0
            and n >= 30
            and n < 95
            and last_me == 'C'
            and last_opp == 'C'
            and rng.random() < 0.02
        ):
            return 'D'

    return 'C'
